import { readFile, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { build } from 'esbuild';

const packageRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
const extensionRoot = join(packageRoot, 'extension');
const entryPath = join(extensionRoot, 'content-script-entry.mjs');
const outputPath = join(extensionRoot, 'content-script.js');
const generatedBanner =
  '// Generated by packages/personal-chrome-companion/scripts/build-content-script.mjs. Do not edit directly.\n' +
  '// biome-ignore-all lint: generated bundle; lint the module source instead\n';

async function bundledContentScript() {
  const result = await build({
    entryPoints: [entryPath],
    absWorkingDir: packageRoot,
    bundle: true,
    charset: 'utf8',
    format: 'iife',
    legalComments: 'none',
    minify: true,
    platform: 'browser',
    sourcemap: false,
    target: ['chrome120'],
    write: false,
  });
  const output = result.outputFiles?.[0]?.text;
  if (typeof output !== 'string') {
    throw new Error('personal Chrome extension bundle produced no JavaScript output');
  }
  const biomeStableOutput = output.replace(
    /^"use strict";(?=\(\(\)=>\{)/,
    "'use strict';\n// biome-ignore format: generated bundle; format the module source instead\n",
  );
  return `${generatedBanner}${biomeStableOutput}`;
}

const expected = await bundledContentScript();
if (process.argv.includes('--write')) {
  await writeFile(outputPath, expected, 'utf8');
} else {
  const observed = await readFile(outputPath, 'utf8');
  if (observed !== expected) {
    throw new Error(
      'personal Chrome content-script.js is stale; run pnpm --filter @clowder-ai/personal-chrome-companion build:extension:write',
    );
  }
}
